#include <iostream>
#include <string>

int main() {
    int ans = 0;
    bool met = false;
    std::string input;

    while (std::getline(std::cin, input)) {
        int count = 0;
        for (char c : input) {
            if (c == 'B') count++;
        }

        if (input == "BBBBBBBB") {
            ans++;
        } else if (!met) {
            if (count > 0) {
                ans += count;
            }
            met = true;
        }
    }

    std::cout << ans << std::endl;

    return 0;
}

